@FunctionalInterface
interface Greeter {
    String greet(String name);

    default String loud(String name) {
        return greet(name).toUpperCase();
    }

    static Greeter polite() {
        return n -> "Dear " + n;
    }
}

public class Main {
    public static void main(String[] args) {
        Greeter g = n -> "Hi " + n;
        System.out.println(g.loud("ram") + " | " + Greeter.polite().greet("Sita"));
    }
}
